(()=>{
const root=document.querySelector('#main'),KEY='batchline-v1';
const starter={lots:[
{id:'LOT-4101',name:'Raw cacao nibs',supplier:'Konkan Pantry Co-op',received:'2026-10-20',expiry:'2027-02-18',qty:12,unit:'kg',cost:760,allergens:['Coconut traces'],status:'Available',storage:'Cool dry shelf B2'},
{id:'LOT-4102',name:'Cane jaggery',supplier:'Konkan Pantry Co-op',received:'2026-10-21',expiry:'2027-01-12',qty:18,unit:'kg',cost:118,allergens:[],status:'Available',storage:'Dry shelf A1'},
{id:'LOT-4103',name:'Rolled oats',supplier:'Maharashtra Grain Works',received:'2026-10-19',expiry:'2027-03-03',qty:8,unit:'kg',cost:142,allergens:['Gluten'],status:'Available',storage:'Dry shelf A3'},
{id:'LOT-4104',name:'Roasted peanuts',supplier:'Sahyadri Growers',received:'2026-10-22',expiry:'2026-12-28',qty:4.5,unit:'kg',cost:210,allergens:['Peanuts'],status:'Available',storage:'Airtight bin C1'},
{id:'LOT-4105',name:'Cocoa butter',supplier:'West Coast Ingredients',received:'2026-10-18',expiry:'2027-05-10',qty:6,unit:'kg',cost:890,allergens:[],status:'Available',storage:'Cool cabinet D1'},
{id:'LOT-4106',name:'Sea salt flakes',supplier:'Konkan Pantry Co-op',received:'2026-10-15',expiry:'2028-01-01',qty:2,unit:'kg',cost:320,allergens:[],status:'Available',storage:'Dry shelf A2'}],batches:[
{id:'B-261023-01',product:'Cacao + jaggery bites',date:'2026-10-23',made:96,unit:'packs',status:'Released',lots:[{id:'LOT-4101',qty:1.8},{id:'LOT-4102',qty:2.4},{id:'LOT-4106',qty:.04}],supplier:'—',orders:64,waste:3,notes:'Morning run · demo record'},
{id:'B-261022-02',product:'Cocoa oat squares',date:'2026-10-22',made:72,unit:'packs',status:'On hold',lots:[{id:'LOT-4103',qty:2.1},{id:'LOT-4105',qty:1.25},{id:'LOT-4102',qty:1.4}],supplier:'—',orders:0,waste:2,notes:'Packaging check pending'},
{id:'B-261021-01',product:'Peanut cacao crunch',date:'2026-10-21',made:48,unit:'jars',status:'Released',lots:[{id:'LOT-4101',qty:1.1},{id:'LOT-4104',qty:1.6},{id:'LOT-4102',qty:.9}],supplier:'—',orders:42,waste:1,notes:'Afternoon run · demo record'},
{id:'B-261020-01',product:'Salted cacao nibs',date:'2026-10-20',made:60,unit:'packs',status:'Dispatched',lots:[{id:'LOT-4101',qty:1.3},{id:'LOT-4106',qty:.025}],supplier:'—',orders:58,waste:2,notes:'Market stall delivery · demo record'}],suppliers:[{name:'Konkan Pantry Co-op',contact:'orders@konkanpantry.example',lead:'2–3 days',rating:'Verified locally',notes:'Dry goods · sample supplier'},{name:'Maharashtra Grain Works',contact:'dispatch@mgw.example',lead:'4 days',rating:'Documentation pending',notes:'Oats and grains · sample supplier'},{name:'Sahyadri Growers',contact:'hello@sahyadri.example',lead:'1–2 days',rating:'Verified locally',notes:'Nuts and seasonal produce · sample supplier'},{name:'West Coast Ingredients',contact:'sales@westcoast.example',lead:'5 days',rating:'Verified locally',notes:'Cocoa products · sample supplier'}],checks:[{id:'QC-5208',type:'Fridge temperature',value:'4.2 °C',time:'09:20',result:'Within target',batch:'B-261023-01',note:'Chiller 01 · sample'},{id:'QC-5207',type:'Packaging seal',value:'Pass',time:'08:48',result:'Pass',batch:'B-261023-01',note:'12-pack spot check'},{id:'QC-5206',type:'Batch release',value:'Signed off',time:'08:12',result:'Pass',batch:'B-261021-01',note:'Sample record'}],activity:[{title:'Batch released',detail:'B-261023-01 · 96 packs',time:'09:32'},{title:'Lot received',detail:'LOT-4106 · sea salt flakes',time:'Yesterday'},{title:'Mock trace completed',detail:'Cacao nibs · 3 downstream batches',time:'Yesterday'}],flags:[],shipments:[{id:'OUT-9001',batch:'B-261023-01',destination:'Kopra Market Stall',qty:32,date:'2026-10-23',reference:'Morning crate'},{id:'OUT-9002',batch:'B-261023-01',destination:'Neighbourhood Pantry',qty:32,date:'2026-10-23',reference:'Route 02'},{id:'OUT-9003',batch:'B-261021-01',destination:'Sunday Market Collective',qty:42,date:'2026-10-22',reference:'Market order'},{id:'OUT-9004',batch:'B-261020-01',destination:'Kopra Market Stall',qty:58,date:'2026-10-21',reference:'Earlier run'}]};
let state=load(),page=location.hash.slice(1)||'home',stockQ='',batchQ='',stockFilter='All lots',batchFilter='All runs',traceQ='',traceMode='forward',recorder=null,spinning=true;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');return {...structuredClone(starter),...x,shipments:x.shipments||structuredClone(starter.shipments)}}catch{return structuredClone(starter)}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{return false}}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;document.querySelector('#toast-region').append(t);setTimeout(()=>t.remove(),3300)}
function fmt(n){return new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(n)}
function badge(s){const c=s==='Released'||s==='Available'||s==='Pass'||s==='Within target'?'':s==='On hold'||s==='Documentation pending'?'warn':s==='Dispatched'?'blue':'muted';return `<span class="tag ${c}">${esc(s.toUpperCase())}</span>`}
function viewbar(n){return `<div class="viewbar"><div class="breadcrumb">BATCHLINE <b>/ ${n.toUpperCase()}</b></div><div class="viewtools"><span>LOCAL RECORD · ${state.batches.length} RUNS</span><button class="button small" data-go="production">＋ New production run</button></div></div>`}
function heading(idx,label,title,desc,button=''){return `<div class="page-heading"><div><div class="eyebrow">${idx} / ${label.toUpperCase()}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function titleCase(s){return esc(s).replace(/\b\w/g,c=>c.toUpperCase())}
function home(){const open=state.batches.filter(b=>b.status==='On hold').length;const exp=state.lots.filter(l=>new Date(l.expiry)<new Date(Date.now()+30*86400000)).length;return `<section class="view">${viewbar('Production floor')}<div class="hero"><div class="hero-copy"><div class="eyebrow">A TRACEABILITY WORKBENCH FOR SMALL FOOD MAKERS</div><h1>Every batch<br>has a <em>backstory.</em></h1><p>Connect an ingredient lot to the run it entered, then trace the finished batch to its next stop. Keep the operation small, legible, and ready for a fast answer.</p><div class="hero-actions"><button class="button" data-go="production">Start a production run <span class="arrow">↗</span></button><button class="button secondary" data-go="trace">Trace an ingredient lot</button></div><div class="hero-note"><i>↳</i> THANE FIELD EDITION · DEMO LOTS ARE FICTIONAL</div></div><div class="vessel-stage" id="vessel-stage"><canvas class="vessel-canvas" id="vessel-canvas" aria-label="Interactive 3D stainless micro-batch mixing vessel"></canvas><div class="vessel-meta top"><span><strong>OBJ. 01</strong> / MIXING VESSEL</span><span>DRAG TO ORBIT</span></div><div class="scene-controls"><button data-action="spin" aria-label="Pause or resume vessel motion">Ⅱ</button><button data-action="reset-vessel" aria-label="Reset vessel view">⌖</button></div><span class="scene-stamp stamp-a">SMALL RUN / 01</span><span class="scene-stamp stamp-b">LOT-IN / LOT-OUT</span><span class="scene-stamp stamp-c">TRACEABLE BY DESIGN</span><div class="vessel-meta bottom"><span>STAINLESS / FOOD-GRADE STUDY</span><span>LOCAL 3D SCENE</span></div></div></div><div class="stat-strip"><div class="stat"><span class="stat-mark">◉</span><span><small>INGREDIENT LOTS</small><strong>${String(state.lots.length).padStart(2,'0')} on hand</strong></span></div><div class="stat"><span class="stat-mark">↗</span><span><small>RUNS THIS WEEK</small><strong>${state.batches.length} recorded</strong></span></div><div class="stat"><span class="stat-mark">◌</span><span><small>QUALITY HOLDS</small><strong>${String(open).padStart(2,'0')} to review</strong></span></div><div class="stat"><span class="stat-mark">⌛</span><span><small>EXPIRY WATCH</small><strong>${String(exp).padStart(2,'0')} in 30 days</strong></span></div></div><div class="section-head"><div><span class="section-index">01 / CHAIN OF CUSTODY</span><h2>One ingredient. Every destination.</h2><p>Follow a lot forward into production, or a batch back to its inputs.</p></div><button class="button secondary small" data-go="trace">Open trace desk ↗</button></div><div class="home-bottom"><div class="surface flow-panel"><div class="eyebrow">TRACE DEMO / ${esc(state.lots[0]?.id||'LOT')}</div><h3>From receiving bay to customer order.</h3><div class="flow-row"><div class="flow-node"><small>01 / RECEIVED</small><strong>${esc(state.lots[0]?.name||'Ingredient lot')}</strong></div><span class="flow-arrow">→</span><div class="flow-node"><small>02 / CONVERTED</small><strong>${state.batches.filter(b=>b.lots?.some(l=>l.id===state.lots[0]?.id)).length} batch runs</strong></div><span class="flow-arrow">→</span><div class="flow-node"><small>03 / DISPATCHED</small><strong>Trade destinations</strong></div></div><div class="flow-foot"><span>TRACE PATH / LIVE FROM LOCAL DATA</span><span>NO CLOUD CONNECTION</span></div></div><div class="surface activity"><div class="eyebrow">SHIFT NOTES / RECENT</div><h3 class="panel-title">On the floor.</h3>${state.activity.slice(0,3).map(a=>`<div class="activity-row"><span class="activity-dot">↗</span><span><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></span><time>${esc(a.time)}</time></div>`).join('')}</div></div><p class="footnote">BATCHLINE / OPERATIONAL TRACEABILITY DEMO · SAMPLE RECORDS ARE FICTIONAL · NOT A FOOD-SAFETY CERTIFICATION OR COMPLIANCE SYSTEM</p></section>`}
function stock(){const data=state.lots.filter(l=>(stockFilter==='All lots'||(stockFilter==='Low stock'?l.qty<5:stockFilter==='On hold'?l.status==='On hold':stockFilter==='Expiring soon'?new Date(l.expiry)<new Date(Date.now()+45*86400000):l.status==='Available'))&&(!stockQ||`${l.id} ${l.name} ${l.supplier} ${l.allergens.join(' ')}`.toLowerCase().includes(stockQ.toLowerCase())));return `<section class="view">${viewbar('Ingredient lots')}<div class="page-content">${heading('01','Receiving & stock','Know what went in.','Ingredient lots keep their supplier, date, quantity, storage, and allergen context together.',`<button class="button" data-go="new-lot">＋ Receive a lot</button>`)}<div class="toolbar"><div class="filter-group">${['All lots','Available','Low stock','Expiring soon','On hold'].map(x=>`<button class="filter ${stockFilter===x?'active':''}" data-stock-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div><input class="search-box" id="stock-search" type="search" placeholder="Search lot, ingredient, supplier…" value="${esc(stockQ)}"></div><div class="table-wrap"><table><thead><tr><th>LOT / INGREDIENT</th><th>SUPPLIER</th><th>ON HAND</th><th>EXPIRY</th><th>ALLERGENS</th><th>STATUS</th><th></th></tr></thead><tbody>${data.map(l=>`<tr><td><strong>${esc(l.id)}</strong><span class="subtext">${esc(l.name)} · ${esc(l.storage)}</span></td><td>${esc(l.supplier)}</td><td><strong>${fmt(l.qty)} ${esc(l.unit)}</strong><span class="subtext">₹${fmt(l.cost)} / unit</span></td><td>${esc(l.expiry)}</td><td>${l.allergens.length?l.allergens.map(a=>`<span class="tag warn">${esc(a)}</span>`).join(' '):'<span class="tag muted">NONE RECORDED</span>'}</td><td>${badge(l.status)}</td><td><button class="text-button" data-lot-trace="${esc(l.id)}">Trace ↗</button></td></tr>`).join('')||'<tr><td colspan="7">No lots match. Change filters or receive an ingredient lot.</td></tr>'}</tbody></table></div><p class="footnote">${data.length} LOTS SHOWN · QUANTITIES ARE MANUALLY ENTERED AND STORED ON THIS DEVICE.</p></div></section>`}
function newLot(){return `<section class="view">${viewbar('Receive ingredient lot')}<div class="page-content">${heading('02','Receiving bay','Log what arrived.','Keep the supplier lot code and your internal lot ID linked. This demo does not verify supplier records or product safety.')}<div class="form-layout"><form id="lot-form" class="form-panel"><div class="eyebrow">01 / NEW INGREDIENT LOT</div><h2>Receiving ticket.</h2><div class="form-grid"><div class="field"><label>INGREDIENT NAME</label><input class="input" name="name" required placeholder="e.g. roasted sesame"></div><div class="field"><label>INTERNAL LOT ID</label><input class="input" name="id" placeholder="Auto-generated if blank"></div><div class="field"><label>SUPPLIER</label><select class="select" name="supplier">${state.suppliers.map(s=>`<option>${esc(s.name)}</option>`).join('')}<option>New / not listed</option></select></div><div class="field"><label>SUPPLIER LOT CODE</label><input class="input" name="supplierLot" placeholder="Code from the supplier label"></div><div class="field"><label>QUANTITY RECEIVED</label><input class="input" type="number" name="qty" required min="0.01" step="0.01" placeholder="0.00"></div><div class="field"><label>UNIT</label><select class="select" name="unit"><option>kg</option><option>g</option><option>L</option><option>units</option><option>packs</option></select></div><div class="field"><label>COST PER UNIT (₹)</label><input class="input" type="number" name="cost" min="0" step="0.01" placeholder="Optional"></div><div class="field"><label>BEST BEFORE / EXPIRY</label><input class="input" type="date" name="expiry"></div><div class="field"><label>RECEIVED DATE</label><input class="input" type="date" name="received" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>STORAGE LOCATION</label><input class="input" name="storage" placeholder="Shelf, fridge, bin…"></div><div class="field wide"><label>ALLERGENS / CROSS-CONTACT NOTES</label><div class="checks">${['Gluten','Peanuts','Tree nuts','Milk','Soy','Sesame','Egg','Coconut traces'].map(x=>`<label class="check"><input type="checkbox" name="allergen" value="${x}">${x}</label>`).join('')}</div></div><div class="field wide"><label>RECEIVING NOTE</label><textarea class="textarea" name="note" placeholder="Packaging, seal, temperature note, supplier reference…"></textarea></div></div><div class="button-row" style="margin-top:18px"><button class="button" type="submit">Save ingredient lot ↗</button><button class="button secondary" type="button" data-go="stock">Cancel</button></div></form><aside class="help-panel"><div class="eyebrow">A GOOD LOT RECORD HAS</div><h2>Enough context to trace it later.</h2><div class="help-step"><strong>Supplier name + their lot code</strong><small>Keep the original package label or invoice in your real records.</small></div><div class="help-step"><strong>Received and expiry dates</strong><small>Dates are entered by the operator; the app cannot inspect a package.</small></div><div class="help-step"><strong>Storage and allergen notes</strong><small>Use the source label and your own verified procedures.</small></div><div class="help-step"><strong>Quantity in a consistent unit</strong><small>Production uses the same unit when consuming the lot.</small></div></aside></div></div></section>`}
function batches(){let data=state.batches.filter(b=>(batchFilter==='All runs'||b.status===batchFilter)&&(!batchQ||`${b.id} ${b.product} ${b.notes}`.toLowerCase().includes(batchQ.toLowerCase())));return `<section class="view">${viewbar('Production runs')}<div class="page-content">${heading('03','Production ledger','Small runs. Clear links.','Each production record lists the ingredient lots consumed, output quantity, waste, quality state, and a traceable batch code.',`<button class="button" data-go="production">＋ Start a production run</button>`)}<div class="toolbar"><div class="filter-group">${['All runs','Released','On hold','Dispatched'].map(x=>`<button class="filter ${batchFilter===x?'active':''}" data-batch-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div><input id="batch-search" class="search-box" type="search" placeholder="Find batch code or product…" value="${esc(batchQ)}"></div><div class="table-wrap"><table><thead><tr><th>BATCH / PRODUCT</th><th>PRODUCED</th><th>INPUT LOTS</th><th>UNITS SHIPPED</th><th>WASTE</th><th>DATE</th><th>STATE</th><th></th></tr></thead><tbody>${data.map(b=>`<tr><td><strong>${esc(b.id)}</strong><span class="subtext">${esc(b.product)}</span></td><td>${fmt(b.made)} ${esc(b.unit)}</td><td>${b.lots.map(x=>esc(x.id)).join(', ')}</td><td>${fmt(b.orders||0)} units shipped</td><td>${fmt(b.waste||0)} ${esc(b.unit)}</td><td>${esc(b.date)}</td><td>${badge(b.status)}</td><td><button class="text-button" data-batch-trace="${esc(b.id)}">Trace ↗</button>${b.status==='On hold'?`<button class="text-button" data-release="${esc(b.id)}">Release</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8">No production runs match these filters.</td></tr>'}</tbody></table></div><p class="footnote">RUNS AND ORDER COUNTS ARE OPERATOR-ENTERED SAMPLE RECORDS; THEY ARE NOT CONNECTED TO SALES OR POS SYSTEMS.</p></div></section>`}
function production(){return `<section class="view">${viewbar('New production run')}<div class="page-content">${heading('04','Batch room','Record a production run.','Select the ingredient lots actually used. Batchline will decrement their on-hand quantity and preserve the lot-to-batch relationship.')}<div class="form-layout"><form id="batch-form" class="form-panel"><div class="eyebrow">01 / PRODUCTION TICKET</div><h2>What did this run make?</h2><div class="form-grid"><div class="field"><label>PRODUCT / RECIPE NAME</label><input class="input" name="product" required placeholder="Product name"></div><div class="field"><label>BATCH CODE</label><input class="input" name="id" placeholder="Auto-generated if blank"></div><div class="field"><label>OUTPUT QUANTITY</label><input class="input" name="made" type="number" min="1" required placeholder="Finished units"></div><div class="field"><label>OUTPUT UNIT</label><select class="select" name="unit"><option>packs</option><option>jars</option><option>trays</option><option>loaves</option><option>units</option></select></div><div class="field"><label>WASTE / REJECTS</label><input class="input" name="waste" type="number" min="0" step="0.1" value="0"></div><div class="field"><label>RUN STATE</label><select class="select" name="status"><option>On hold</option><option>Released</option></select></div><div class="field wide"><label>INGREDIENT LOTS USED · ENTER AMOUNT IN LOT'S UNIT</label><div class="checks">${state.lots.filter(l=>l.status!=='On hold').map(l=>`<label class="check lot-check"><input type="checkbox" name="lot" value="${esc(l.id)}"><span>${esc(l.name)} <small>${esc(l.id)} · ${fmt(l.qty)} ${esc(l.unit)} left</small><input class="input use-qty" data-use-qty="${esc(l.id)}" type="number" min=".01" step=".01" max="${l.qty}" placeholder="Qty ${esc(l.unit)}" disabled></span></label>`).join('')||'<span>No available lots. Receive a lot first.</span>'}</div></div><div class="field wide"><label>RUN NOTE</label><textarea class="textarea" name="notes" placeholder="Shift, process note, recipe revision…"></textarea></div></div><div class="button-row" style="margin-top:18px"><button class="button" type="submit">Save batch record ↗</button><button class="button secondary" type="button" data-go="batches">Cancel</button></div></form><aside class="help-panel"><div class="eyebrow">THE TRACE CHAIN</div><h2>Inputs become outputs.</h2><div class="help-step"><strong>1 / Choose exact lots</strong><small>Don't use a general ingredient name when the package carries a lot code.</small></div><div class="help-step"><strong>2 / Enter consumed quantity</strong><small>Amounts are checked against the current local lot balance.</small></div><div class="help-step"><strong>3 / Record the output</strong><small>Finished unit count and rejects are stored against this run.</small></div><div class="help-step"><strong>4 / Add checks before release</strong><small>This prototype does not decide whether food is safe to release.</small></div></aside></div></div></section>`}
function trace(){const q=traceQ.trim();let item=null,kind='',related=[];if(q){item=state.lots.find(x=>x.id.toLowerCase()===q.toLowerCase());if(item){kind='lot';related=state.batches.filter(b=>b.lots.some(x=>x.id===item.id))}else{item=state.batches.find(x=>x.id.toLowerCase()===q.toLowerCase());if(item){kind='batch';related=item.lots.map(x=>state.lots.find(l=>l.id===x.id)).filter(Boolean)}}}return `<section class="view">${viewbar('Trace & recall')}<div class="page-content">${heading('04','Trace desk','Find the chain.','Start with an internal lot or a production batch code. Batchline shows connected records from this local demo dataset; it does not contact customers or issue a recall.')}<div class="surface" style="padding:20px"><div class="eyebrow">LOOK UP A RECORD</div><div class="trace-search"><input class="input" id="trace-input" value="${esc(q)}" placeholder="LOT-4101 or B-261023-01"><button class="button" data-action="trace-search">Trace record ↗</button></div><div class="filter-group"><button class="filter ${traceMode==='forward'?'active':''}" data-trace-mode="forward">Forward trace · lot → runs</button><button class="filter ${traceMode==='backward'?'active':''}" data-trace-mode="backward">Backward trace · batch → inputs</button><button class="filter" data-action="mock-recall">Run mock trace exercise</button></div></div>${q&&item?traceResult(item,kind,related):q?`<div class="trace-result" style="margin-top:14px"><strong>No exact record found for “${esc(q)}”.</strong><p class="hint">Check the full lot or batch code. Try LOT-4101 or B-261023-01.</p></div>`:`<div class="trace-result" style="margin-top:14px"><div class="eyebrow">SAMPLE EXERCISE / LOT-4101</div><h2 class="panel-title">A lot should never disappear inside a recipe.</h2><p class="hint">Search <button class="text-button" data-set-trace="LOT-4101">LOT-4101</button> to see its downstream runs, or trace <button class="text-button" data-set-trace="B-261023-01">B-261023-01</button> back to its inputs.</p></div>`}<div class="section-head" style="margin-top:32px"><div><span class="section-index">TRACE EXERCISES</span><h2>Practice the fast answer.</h2></div></div><div class="card-grid"><article class="data-card"><div class="eyebrow">INPUT → OUTPUT</div><h3>Which runs used the cacao?</h3><p>Trace LOT-4101 forward to see the production records and order counts connected to it.</p><button class="text-button" data-set-trace="LOT-4101">Open LOT-4101 →</button></article><article class="data-card"><div class="eyebrow">OUTPUT → INPUT</div><h3>What went into this batch?</h3><p>Trace a finished batch backward to its ingredient lot IDs, source quantities, and supplier names.</p><button class="text-button" data-set-trace="B-261023-01">Open B-261023-01 →</button></article><article class="data-card"><div class="eyebrow">TABLETOP DRILL</div><h3>Run a mock trace.</h3><p>Pick an input lot and calculate the set of local batches and orders it touches.</p><button class="text-button" data-action="mock-recall">Start exercise →</button></article></div><p class="footnote">A TRACE REPORT IS A LOCAL OPERATIONAL SUMMARY. IT IS NOT A FORMAL RECALL NOTICE OR REGULATORY SUBMISSION.</p></div></section>`}
function traceResult(item,kind,related){let batches=kind==='lot'?related:[item],lots=kind==='lot'?[item]:related;const orders=batches.reduce((a,b)=>a+state.shipments.filter(s=>s.batch===b.id).reduce((n,s)=>n+Number(s.qty),0),0),held=batches.filter(b=>b.status==='On hold').length,sends=state.shipments.filter(s=>batches.some(b=>b.id===s.batch));return `<div class="trace-result" style="margin-top:14px"><div class="eyebrow">${kind==='lot'?'FORWARD TRACE / INGREDIENT LOT':'BACKWARD TRACE / PRODUCTION BATCH'}</div><h2 class="panel-title">${esc(item.name||item.product)} <span class="tag blue">${esc(item.id)}</span></h2><p class="hint">${kind==='lot'?`Supplier: ${esc(item.supplier)} · received ${esc(item.received)} · ${fmt(item.qty)} ${esc(item.unit)} currently recorded`:`Produced ${fmt(item.made)} ${esc(item.unit)} on ${esc(item.date)} · state ${esc(item.status)}`}</p><div class="trace-path">${kind==='lot'?`<div class="trace-step"><small>01 / RECEIVED</small><strong>${esc(item.supplier)}</strong><span>${esc(item.id)} · ${esc(item.name)}</span></div><div class="trace-step"><small>02 / ALLOCATED</small><strong>${related.length} linked run${related.length===1?'':'s'}</strong><span>${related.map(b=>esc(b.id)).join(' · ')||'No downstream runs in this sample'}</span></div><div class="trace-step"><small>03 / OUTPUT</small><strong>${fmt(related.reduce((a,b)=>a+Number(b.made),0))} units</strong><span>Across linked production records</span></div><div class="trace-step"><small>04 / DISPATCH LINKS</small><strong>${orders} order count</strong><span>Sample count entered by operator</span></div>`:`<div class="trace-step"><small>01 / INPUT LOTS</small><strong>${lots.length} linked lots</strong><span>${lots.map(l=>esc(l.id)).join(' · ')}</span></div><div class="trace-step"><small>02 / SUPPLIERS</small><strong>${new Set(lots.map(l=>l.supplier)).size} suppliers</strong><span>${[...new Set(lots.map(l=>l.supplier))].map(esc).join(' · ')}</span></div><div class="trace-step"><small>03 / BATCH OUTPUT</small><strong>${fmt(item.made)} ${esc(item.unit)}</strong><span>${fmt(item.waste||0)} ${esc(item.unit)} recorded as waste</span></div><div class="trace-step"><small>04 / DESTINATION</small><strong>${fmt(item.orders||0)} order count</strong><span>Destination records are demo totals, not named customers</span></div>`}</div><div class="trace-impact"><div class="impact"><small>CONNECTED RUNS</small><strong>${batches.length}</strong></div><div class="impact"><small>UNITS SHIPPED</small><strong>${orders}</strong></div><div class="impact"><small>ON-HOLD RUNS</small><strong>${held}</strong></div></div><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>${kind==='lot'?'DOWNSTREAM BATCH':'INPUT LOT'}</th><th>${kind==='lot'?'PRODUCT / DATE':'SUPPLIER / EXPIRY'}</th><th>QUANTITY LINKED</th><th>STATE</th><th></th></tr></thead><tbody>${kind==='lot'?related.map(b=>`<tr><td><strong>${esc(b.id)}</strong></td><td>${esc(b.product)}<span class="subtext">${esc(b.date)}</span></td><td>${fmt(b.lots.find(x=>x.id===item.id)?.qty||0)} ${esc(item.unit)}</td><td>${badge(b.status)}</td><td><button class="text-button" data-set-trace="${esc(b.id)}">Trace batch →</button></td></tr>`).join(''):item.lots.map(x=>{const l=state.lots.find(y=>y.id===x.id);return l?`<tr><td><strong>${esc(l.id)}</strong></td><td>${esc(l.name)}<span class="subtext">${esc(l.supplier)} · expires ${esc(l.expiry)}</span></td><td>${fmt(x.qty)} ${esc(l.unit)}</td><td>${badge(l.status)}</td><td><button class="text-button" data-set-trace="${esc(l.id)}">Trace lot →</button></td></tr>`:''}).join('')||'<tr><td colspan="5">No inputs recorded.</td></tr>'}</tbody></table></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>CONNECTED DISPATCH</th><th>DESTINATION</th><th>QUANTITY</th><th>DATE</th><th>REFERENCE</th></tr></thead><tbody>${sends.map(s=>`<tr><td><strong>${esc(s.id)}</strong><span class="subtext">${esc(s.batch)}</span></td><td>${esc(s.destination)}</td><td>${fmt(s.qty)}</td><td>${esc(s.date)}</td><td>${esc(s.reference||'—')}</td></tr>`).join('')||'<tr><td colspan="5">No dispatch record connected to these batches.</td></tr>'}</tbody></table></div><p class="hint">This relationship reflects only records entered in this browser. An empty link means “not recorded here,” not “did not happen.”</p></div>`}
function dispatches(){const shipped=id=>state.shipments.filter(s=>s.batch===id).reduce((a,s)=>a+Number(s.qty),0),ready=state.batches.filter(b=>b.status!=='On hold'&&b.made-shipped(b.id)-Number(b.waste||0)>0);return `<section class="view">${viewbar('Dispatch ledger')}<div class="page-content">${heading('05','Delivery handoff','Follow the batch to its next stop.','Record a finished batch leaving the workbench, without collecting individual customer data. These destinations are fictional demo records.')}<div class="form-layout"><form id="dispatch-form" class="form-panel"><div class="eyebrow">01 / OUTGOING HANDOFF</div><h2>Dispatch note.</h2><div class="form-grid"><div class="field wide"><label>RELEASED BATCH</label><select class="select" name="batch" required>${ready.map(b=>`<option value="${esc(b.id)}">${esc(b.id)} · ${esc(b.product)} · ${Math.max(0,b.made-shipped(b.id))} ${esc(b.unit)} left</option>`).join('')}</select></div><div class="field"><label>DESTINATION / TRADE CUSTOMER</label><input class="input" name="destination" required placeholder="Shop, market, or route name"></div><div class="field"><label>QUANTITY SENT</label><input class="input" name="qty" type="number" min="1" step="1" required placeholder="Finished units"></div><div class="field"><label>DISPATCH DATE</label><input class="input" name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>DELIVERY REFERENCE</label><input class="input" name="reference" placeholder="Crate, invoice, route…"></div></div><div class="button-row" style="margin-top:17px"><button class="button" type="submit">Save dispatch note ↗</button></div><p class="hint">Do not enter consumer names, phone numbers, or home addresses in this demo.</p></form><aside class="help-panel"><div class="eyebrow">WHY THIS PAGE EXISTS</div><h2>A batch is not finished at the mixer.</h2><div class="help-step"><strong>Keep a destination-level quantity</strong><small>If a batch touches a concern, see which trade destinations received it.</small></div><div class="help-step"><strong>Use a trade reference</strong><small>Connect your own invoice or crate number without storing a customer's private details.</small></div><div class="help-step"><strong>Reconcile against output</strong><small>Available quantity is calculated from produced units minus recorded dispatches and waste.</small></div></aside></div><div class="section-head" style="margin-top:30px"><div><span class="section-index">OUTGOING RECORDS</span><h2>Where each run travelled.</h2></div></div><div class="table-wrap"><table><thead><tr><th>DISPATCH / BATCH</th><th>PRODUCT</th><th>DESTINATION</th><th>QUANTITY</th><th>DATE</th><th>REFERENCE</th></tr></thead><tbody>${state.shipments.map(s=>{const b=state.batches.find(x=>x.id===s.batch);return `<tr><td><strong>${esc(s.id)}</strong><span class="subtext">${esc(s.batch)}</span></td><td>${esc(b?.product||'Batch removed')}</td><td>${esc(s.destination)}</td><td>${fmt(s.qty)} ${esc(b?.unit||'units')}</td><td>${esc(s.date)}</td><td>${esc(s.reference||'—')}</td></tr>`}).join('')||'<tr><td colspan="6">No dispatch notes yet.</td></tr>'}</tbody></table></div><p class="footnote">DISPATCH NOTES ARE LOCAL OPERATIONAL RECORDS. THEY DO NOT SEND ORDERS OR RECALL MESSAGES.</p></div></section>`}
function quality(){const types=['Fridge temperature','Freezer temperature','Packaging seal','Sanitation check','Visual inspection','Batch release','Other'];return `<section class="view">${viewbar('Quality log')}<div class="page-content">${heading('05','Shift checks','Record the check, not just the result.','A time-stamped local log helps a small team keep a consistent process. Targets and pass/fail decisions must come from your own reviewed procedure.')}<div class="quality-grid"><form class="form-panel" id="check-form"><div class="eyebrow">01 / ADD A CHECK</div><h2>Shift check card.</h2><div class="form-grid"><div class="field"><label>CHECK TYPE</label><select class="select" name="type">${types.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>READING / RESULT</label><input class="input" name="value" required placeholder="4.1 °C / Pass / Note"></div><div class="field"><label>RELATED BATCH</label><select class="select" name="batch"><option value="">Not batch-specific</option>${state.batches.map(b=>`<option value="${esc(b.id)}">${esc(b.id)} · ${esc(b.product)}</option>`).join('')}</select></div><div class="field"><label>RESULT LABEL</label><select class="select" name="result"><option>Within target</option><option>Pass</option><option>Review needed</option><option>Fail / hold</option><option>Information only</option></select></div><div class="field wide"><label>SHIFT NOTE</label><textarea class="textarea" name="note" placeholder="Equipment, location, operator initials, follow-up…"></textarea></div></div><div class="button-row" style="margin-top:17px"><button class="button" type="submit">Save shift check ↗</button></div></form><aside class="help-panel"><div class="eyebrow">LOCAL CHECKLISTS</div><h2>Keep the human sign-off.</h2><p class="hint">Batchline stores what your team enters. It doesn't set safe food temperatures, determine whether a product is safe, or replace a validated food safety plan.</p><div class="help-step"><strong>Use reviewed targets</strong><small>Configure them in the kitchen's approved process before production use.</small></div><div class="help-step"><strong>Record the device and location</strong><small>A temperature without equipment context can be hard to interpret later.</small></div><div class="help-step"><strong>Hold and investigate when needed</strong><small>Never rely on an app's generic status label to release food.</small></div></aside></div><div class="section-head" style="margin-top:30px"><div><span class="section-index">SHIFT RECORDS</span><h2>Checks entered.</h2></div><button class="button secondary small" data-action="export-checks">Export CSV ↓</button></div><div class="table-wrap quality-log"><table><thead><tr><th>CHECK ID / TYPE</th><th>READING</th><th>TIME</th><th>RELATED BATCH</th><th>RESULT</th><th>NOTE</th></tr></thead><tbody>${state.checks.map(c=>`<tr><td><strong>${esc(c.id)}</strong><span class="subtext">${esc(c.type)}</span></td><td>${esc(c.value)}</td><td>${esc(c.time)}</td><td>${esc(c.batch||'—')}</td><td>${badge(c.result)}</td><td>${esc(c.note)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">LOCAL LOG ONLY · NO CALIBRATION, SENSORS, AUTOMATIC ALERTS OR CERTIFICATION CONNECTION.</p></div></section>`}
function suppliers(){return `<section class="view">${viewbar('Supplier directory')}<div class="page-content">${heading('06','Supplier records','Know who supplied the lot.','Keep a small directory beside receiving records. Supplier ratings and verification labels below are demo-only placeholders, not independently confirmed.',`<button class="button" data-action="add-supplier">＋ Add a supplier</button>`)}<div class="surface" style="padding:5px 17px">${state.suppliers.map(s=>`<div class="supplier-row"><span class="supplier-initial">${esc(s.name[0]||'?')}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.contact)} · ${esc(s.notes)}</small></span><span class="tag ${s.rating.includes('pending')?'warn':''}">${esc(s.rating.toUpperCase())}</span><span class="subtext">Lead time · ${esc(s.lead)}</span></div>`).join('')}</div><div class="section-head" style="margin-top:30px"><div><span class="section-index">SUPPLIER COVERAGE</span><h2>Linked receiving records.</h2></div></div><div class="table-wrap"><table><thead><tr><th>SUPPLIER</th><th>LOTS RECEIVED</th><th>INGREDIENTS</th><th>LAST RECEIPT</th><th>OPEN HOLDS</th></tr></thead><tbody>${state.suppliers.map(s=>{const ls=state.lots.filter(l=>l.supplier===s.name);return `<tr><td><strong>${esc(s.name)}</strong></td><td>${ls.length}</td><td>${[...new Set(ls.map(l=>l.name))].map(esc).join(', ')||'No lots linked'}</td><td>${ls.map(l=>l.received).sort().reverse()[0]||'—'}</td><td>${ls.filter(l=>l.status==='On hold').length}</td></tr>`}).join('')}</tbody></table></div><p class="footnote">NO SUPPLIER EMAILS OR ORDERS ARE SENT FROM THIS DEMO.</p></div></section>`}
function records(){const total=state.lots.reduce((a,l)=>a+Number(l.qty),0);return `<section class="view">${viewbar('Records & export')}<div class="page-content">${heading('07','Archive & operations','Take the records with you.','Export a portable snapshot or run a mock trace exercise. The backup contains your local metadata and entered records; it excludes images, documents, and external supplier evidence.')}<div class="card-grid"><article class="data-card"><div class="eyebrow">01 / INGREDIENTS</div><div class="metric">${state.lots.length}</div><p>Tracked ingredient lots</p></article><article class="data-card"><div class="eyebrow">02 / PRODUCTION</div><div class="metric">${state.batches.length}</div><p>Recorded production runs</p></article><article class="data-card"><div class="eyebrow">03 / ON-HAND</div><div class="metric">${fmt(total)}<small style="font:13px var(--sans);color:var(--muted)"> mixed units</small></div><p>Quantities are not converted across units</p></article></div><div class="card-grid" style="margin-top:13px"><article class="data-card"><div class="eyebrow">PORTABILITY</div><h3>Export workspace.</h3><p>Save a JSON backup with ingredients, batches, checks, suppliers, and activity.</p><button class="button small" data-action="backup">Download JSON backup ↓</button></article><article class="data-card"><div class="eyebrow">RESTORE</div><h3>Load a backup copy.</h3><p>Restore a previous Batchline workspace after reviewing the replacement warning.</p><label class="button secondary small" for="restore-file">Choose JSON ↑</label><input id="restore-file" type="file" accept="application/json" hidden></article><article class="data-card"><div class="eyebrow">RESET DEMO</div><h3>Return to sample data.</h3><p>Replace this browser's Batchline records with the staged fictional data.</p><button class="button alert small" data-action="reset-demo">Restore sample workspace</button></article></div><div class="surface" style="padding:19px;margin-top:14px"><div class="eyebrow">OPERATIONAL BOUNDARY</div><h3 class="panel-title">This is a traceability study, not a compliance product.</h3><p class="hint">No account system, cloud database, sensor integration, sales/POS connector, supplier verification, or AI model is connected. Data lives in browser storage on this device. Do not treat a generated report as an official recall, safety determination, or regulatory submission.</p></div><p class="footnote">EXPORTS ARE PORTABLE JSON / CSV ONLY · NO DATA LEAVES THIS DEVICE UNLESS YOU DOWNLOAD AND SHARE IT.</p></div></section>`}
function pageHeading(p){const pages={home,stock,batches,trace,dispatch:dispatches,quality,suppliers,records,'new-lot':newLot,production};return (pages[p]||home)()}
function render(){document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===page));document.querySelector('#lot-count').textContent=String(state.lots.length).padStart(2,'0');root.innerHTML=pageHeading(page);bindPage();if(page==='home')initVessel();}
function log(title,detail){state.activity.unshift({title,detail,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})});state.activity=state.activity.slice(0,20);save()}
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'smooth'})}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function addLot(form){const f=new FormData(form),name=f.get('name').trim(),id=f.get('id').trim()||`LOT-${Date.now().toString().slice(-5)}`;if(state.lots.some(l=>l.id.toLowerCase()===id.toLowerCase())){toast('That internal lot ID already exists.');return}const lot={id,name,supplier:f.get('supplier'),supplierLot:f.get('supplierLot'),received:f.get('received')||new Date().toISOString().slice(0,10),expiry:f.get('expiry')||'Not recorded',qty:Number(f.get('qty')),unit:f.get('unit'),cost:Number(f.get('cost')||0),allergens:f.getAll('allergen'),status:'Available',storage:f.get('storage')||'Storage not recorded',note:f.get('note')};state.lots.unshift(lot);log('Ingredient lot received',`${lot.id} · ${lot.name} · ${lot.qty} ${lot.unit}`);save();toast('Ingredient lot added to this device.');go('stock')}
function addBatch(form){const f=new FormData(form),checks=[...form.querySelectorAll('[name="lot"]:checked')];if(!checks.length){toast('Select at least one ingredient lot.');return}const used=[];for(const c of checks){const l=state.lots.find(x=>x.id===c.value),q=Number(form.querySelector(`[data-use-qty="${CSS.escape(c.value)}"]`).value);if(!q||q>l.qty){toast(`Enter a valid amount for ${l.id}.`);return}used.push({id:l.id,qty:q})}const id=f.get('id').trim()||`B-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(state.batches.length+1).padStart(2,'0')}`;if(state.batches.some(b=>b.id.toLowerCase()===id.toLowerCase())){toast('That batch code already exists. Stock was not changed.');return}used.forEach(x=>{const l=state.lots.find(y=>y.id===x.id);l.qty=Number((l.qty-x.qty).toFixed(3));if(l.qty<=0){l.qty=0;l.status='Depleted'}});const b={id,product:f.get('product').trim(),date:new Date().toISOString().slice(0,10),made:Number(f.get('made')),unit:f.get('unit'),status:f.get('status'),lots:used,orders:0,waste:Number(f.get('waste')||0),notes:f.get('notes')||''};state.batches.unshift(b);log('Production run recorded',`${b.id} · ${b.product} · ${b.made} ${b.unit}`);save();toast(`Batch ${b.id} saved with ${used.length} linked lots.`);go('batches')}
function traceTo(q){traceQ=q;go('trace')}
function mockRecall(){const available=state.lots.filter(l=>l.status==='Available');if(!available.length){traceQ='';toast('No available lots to use for the tabletop drill.');render();return}const l=available[Math.floor(Math.random()*available.length)];traceMode='forward';traceQ=l.id;log('Mock trace exercise run',`${l.id} · ${state.batches.filter(b=>b.lots.some(x=>x.id===l.id)).length} downstream run(s) found in demo data`);go('trace');toast(`Practice trace loaded for ${l.id}. No customers were contacted.`)}
function addDispatch(form){const f=new FormData(form),b=state.batches.find(x=>x.id===f.get('batch'));if(!b)return;const already=state.shipments.filter(s=>s.batch===b.id).reduce((a,s)=>a+Number(s.qty),0),available=Number(b.made)-Number(b.waste||0)-already,q=Number(f.get('qty'));if(q<=0||q>available){toast(`Enter a dispatch quantity up to ${Math.max(0,available)} ${b.unit}.`);return}const d={id:`OUT-${Date.now().toString().slice(-5)}`,batch:b.id,destination:f.get('destination').trim(),qty:q,date:f.get('date')||new Date().toISOString().slice(0,10),reference:f.get('reference')||'Not recorded'};state.shipments.unshift(d);const total=already+q;b.orders=total;if(total>=Number(b.made)-Number(b.waste||0))b.status='Dispatched';log('Dispatch note saved',`${d.batch} · ${d.destination} · ${d.qty} ${b.unit}`);save();toast('Dispatch connected to its production batch.');go('dispatch')}
function addSupplier(){const name=prompt('Supplier or cooperative name:');if(!name?.trim())return;if(state.suppliers.some(s=>s.name.toLowerCase()===name.trim().toLowerCase())){toast('That supplier is already listed.');return}const contact=prompt('Contact email or phone (optional):')||'Not recorded';state.suppliers.unshift({name:name.trim(),contact,lead:'Not recorded',rating:'Not verified',notes:'Added locally'});log('Supplier record added',name.trim());save();render();toast('Supplier saved locally.')}
async function restore(file){try{const parsed=JSON.parse(await file.text()),data=parsed.state||parsed;if(!Array.isArray(data.lots)||!Array.isArray(data.batches)||!Array.isArray(data.suppliers)||!Array.isArray(data.checks)||!Array.isArray(data.shipments))throw Error();if(!confirm('Replace all current Batchline records in this browser with this backup?'))return;state={...structuredClone(starter),...data};save();toast('Workspace backup restored.');render()}catch{toast('Could not read that Batchline JSON backup.')}}
function exportBackup(){const pack={schema:'batchline-v1',exportedAt:new Date().toISOString(),notice:'Demo traceability record; not a compliance certificate.',state};download('batchline-workspace.json',JSON.stringify(pack,null,2));log('Workspace backup exported','JSON downloaded to this device.');toast('Backup downloaded. Keep a separate secure copy.')}
function exportChecks(){const rows=[['id','type','value','time','result','batch','note'],...state.checks.map(c=>[c.id,c.type,c.value,c.time,c.result,c.batch,c.note])];download('batchline-quality-log.csv',rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');toast('Quality log CSV downloaded.')}
function initVessel(){const canvas=document.querySelector('#vessel-canvas');if(!canvas)return;if(!window.THREE){vesselFallback(canvas);return}try{const T=window.THREE,renderer=new T.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'high-performance'});recorder=renderer;renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);renderer.outputEncoding=T.sRGBEncoding;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.14;const scene=new T.Scene(),camera=new T.PerspectiveCamera(32,canvas.clientWidth/canvas.clientHeight,.1,100);camera.position.set(3.4,2.4,6.7);camera.lookAt(0,.05,0);scene.add(new T.HemisphereLight(0xd7f1ff,0x1b3033,1.9));const key=new T.DirectionalLight(0xf4fbff,3.4);key.position.set(-3,5,4);scene.add(key);const rim=new T.DirectionalLight(0xd4f477,2.5);rim.position.set(4,2,-4);scene.add(rim);const warm=new T.PointLight(0xff8c60,.9,7);warm.position.set(-3,-1,3);scene.add(warm);const vessel=new T.Group();scene.add(vessel);const steel=new T.MeshStandardMaterial({color:0xaebfbe,metalness:.88,roughness:.2,side:T.DoubleSide}),steelDark=new T.MeshStandardMaterial({color:0x536a6b,metalness:.76,roughness:.28}),lime=new T.MeshStandardMaterial({color:0xd4f477,metalness:.25,roughness:.24,emissive:0x435c15,emissiveIntensity:.16}),glass=new T.MeshPhysicalMaterial({color:0x729d9a,metalness:.08,roughness:.12,transparent:true,opacity:.32,clearcoat:.9,clearcoatRoughness:.08,side:T.DoubleSide}),orange=new T.MeshStandardMaterial({color:0xff8c60,metalness:.45,roughness:.3});
// A single lathed shell gives the kettle a continuous bowl silhouette rather than stacked primitives.
const profile=[new T.Vector2(.2,-1.03),new T.Vector2(.46,-1.02),new T.Vector2(.62,-.88),new T.Vector2(.73,-.55),new T.Vector2(.77,-.12),new T.Vector2(.76,.35),new T.Vector2(.72,.58),new T.Vector2(.68,.68),new T.Vector2(.61,.68),new T.Vector2(.63,.52),new T.Vector2(.66,.25),new T.Vector2(.65,-.18),new T.Vector2(.59,-.59),new T.Vector2(.46,-.78),new T.Vector2(.22,-.81)];const shell=new T.Mesh(new T.LatheGeometry(profile,96),steel);shell.castShadow=true;shell.receiveShadow=true;vessel.add(shell);const rimRing=new T.Mesh(new T.TorusGeometry(.665,.055,18,96),steelDark);rimRing.rotation.x=Math.PI/2;rimRing.position.y=.68;vessel.add(rimRing);const polished=new T.Mesh(new T.TorusGeometry(.665,.018,12,96),new T.MeshStandardMaterial({color:0xf2fbff,metalness:.9,roughness:.15}));polished.rotation.x=Math.PI/2;polished.position.y=.73;vessel.add(polished);
// Glass inspection window and luminous ingredient surface.
const windowMesh=new T.Mesh(new T.SphereGeometry(.69,48,32,0,Math.PI*2,Math.PI*.38,Math.PI*.45),glass);windowMesh.position.y=-.12;vessel.add(windowMesh);const food=new T.Mesh(new T.CircleGeometry(.62,80),new T.MeshStandardMaterial({color:0x8eb94e,metalness:.12,roughness:.28,emissive:0x253b0d,emissiveIntensity:.28,side:T.DoubleSide}));food.rotation.x=-Math.PI/2;food.position.y=.22;vessel.add(food);const ripples=[];for(let i=0;i<3;i++){const r=new T.Mesh(new T.TorusGeometry(.16+i*.115,.008,8,72),new T.MeshBasicMaterial({color:i===1?0xf4efbc:0xd4f477,transparent:true,opacity:.44-i*.08}));r.rotation.x=Math.PI/2;r.position.y=.235+i*.001;vessel.add(r);ripples.push(r)}
// Motor head, shaft, cross-paddle and fasteners.
const motor=new T.Mesh(new T.CylinderGeometry(.31,.35,.32,64),steelDark);motor.position.y=1.01;vessel.add(motor);const cap=new T.Mesh(new T.CylinderGeometry(.28,.3,.08,64),steel);cap.position.y=1.21;vessel.add(cap);const capRing=new T.Mesh(new T.TorusGeometry(.28,.018,10,64),lime);capRing.position.y=1.26;vessel.add(capRing);const shaft=new T.Mesh(new T.CylinderGeometry(.035,.035,.83,24),steelDark);shaft.position.y=.34;vessel.add(shaft);const paddle=new T.Group();paddle.position.y=-.02;vessel.add(paddle);for(let i=0;i<3;i++){const blade=new T.Mesh(new T.BoxGeometry(.75,.055,.12),i===1?lime:steelDark);blade.position.y=-.28+i*.23;blade.rotation.y=i*Math.PI/3;paddle.add(blade)}
// Reinforced feet, drain valve, pipe and clamp bands.
for(let i=0;i<3;i++){const a=i*Math.PI*2/3;const leg=new T.Mesh(new T.CylinderGeometry(.055,.075,.65,24),steelDark);leg.position.set(Math.cos(a)*.57,-1.26,Math.sin(a)*.57);leg.rotation.z=-Math.cos(a)*.14;leg.rotation.x=Math.sin(a)*.14;vessel.add(leg);const foot=new T.Mesh(new T.CylinderGeometry(.12,.13,.07,32),steelDark);foot.position.set(Math.cos(a)*.6,-1.59,Math.sin(a)*.6);vessel.add(foot)}
const band=new T.Mesh(new T.TorusGeometry(.744,.024,12,96),orange);band.rotation.x=Math.PI/2;band.position.y=-.54;vessel.add(band);const outlet=new T.Mesh(new T.CylinderGeometry(.1,.11,.42,32),steelDark);outlet.rotation.z=Math.PI/2;outlet.position.set(.76,-.65,0);vessel.add(outlet);const valve=new T.Mesh(new T.TorusGeometry(.14,.022,10,40),lime);valve.position.set(1,-.64,0);valve.rotation.y=Math.PI/2;vessel.add(valve);const handle=new T.Mesh(new T.BoxGeometry(.04,.28,.04),orange);handle.position.set(1,-.64,0);vessel.add(handle);
const dust=new T.Group();vessel.add(dust);for(let i=0;i<22;i++){const p=new T.Mesh(new T.SphereGeometry(.018+(i%3)*.007,12,8),i%4===0?orange:lime);const a=i*2.399;p.position.set(Math.cos(a)*(.25+(i%4)*.075),-.25+(i%8)*.075,Math.sin(a)*(.25+(i%4)*.075));dust.add(p)}
const shadow=new T.Mesh(new T.CircleGeometry(1.25,64),new T.MeshBasicMaterial({color:0x081317,transparent:true,opacity:.3}));shadow.rotation.x=-Math.PI/2;shadow.position.y=-1.64;vessel.add(shadow);vessel.rotation.set(-.1,-.45,0);let dragging=false,px=0,py=0,zoom=1;window.__batchlineReset=()=>{vessel.rotation.set(-.1,-.45,0);zoom=1};const observer=new ResizeObserver(()=>{if(!canvas.isConnected)return;renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);camera.aspect=canvas.clientWidth/canvas.clientHeight;camera.updateProjectionMatrix()});observer.observe(canvas);canvas.addEventListener('pointerdown',e=>{dragging=true;px=e.clientX;py=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;vessel.rotation.y+=(e.clientX-px)*.009;vessel.rotation.x=Math.max(-.35,Math.min(.28,vessel.rotation.x+(e.clientY-py)*.006));px=e.clientX;py=e.clientY});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('wheel',e=>{zoom=Math.max(.78,Math.min(1.18,zoom-e.deltaY*.0006));e.preventDefault()},{passive:false});let start=performance.now(),raf;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const tick=now=>{if(!canvas.isConnected){cancelAnimationFrame(raf);observer.disconnect();scene.traverse(o=>{o.geometry?.dispose();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];ms.forEach(m=>{Object.values(m).forEach(v=>v?.isTexture&&v.dispose());m.dispose()})}});renderer.dispose();return}raf=requestAnimationFrame(tick);const t=(now-start)/1000;if(spinning&&!dragging&&!reduced){vessel.rotation.y+=.0012;paddle.rotation.y+=.018}vessel.scale.setScalar(zoom);vessel.position.y=reduced?0:Math.sin(t*.8)*.025;ripples.forEach((r,i)=>{const pulse=(Math.sin(t*1.7+i*1.3)+1)/2;r.scale.setScalar(.74+pulse*.55);r.material.opacity=.2+pulse*.36});dust.children.forEach((p,i)=>{p.position.y=-.35+((t*.09+i*.13)% .58);p.rotation.x=t*.2+i});renderer.render(scene,camera)};raf=requestAnimationFrame(tick);
}catch(e){console.warn('Using illustrated mixer scene',e);vesselFallback(canvas)}}
function vesselFallback(canvas){const holder=document.createElement('div');holder.className='vessel-fallback';holder.innerHTML=`<svg viewBox="0 0 540 440" aria-hidden="true"><defs><linearGradient id="steel" x1="0" x2="1"><stop stop-color="#708584"/><stop offset=".2" stop-color="#e6f0ec"/><stop offset=".48" stop-color="#879c9a"/><stop offset=".72" stop-color="#d9e4e0"/><stop offset="1" stop-color="#627a78"/></linearGradient><linearGradient id="food" x1="0" x2="0" y2="1"><stop stop-color="#d4f477"/><stop offset="1" stop-color="#789c39"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="11"/></filter></defs><ellipse cx="268" cy="367" rx="133" ry="20" fill="#0008" filter="url(#blur)"/><g class="svg-kettle"><path d="M166 101Q167 79 194 73h143q26 8 28 30l-5 13h-189z" fill="url(#steel)" stroke="#e9f4ef" stroke-width="2"/><rect x="185" y="42" width="153" height="44" rx="16" fill="#506867" stroke="#cbd8d3" stroke-width="3"/><ellipse cx="261" cy="44" rx="70" ry="15" fill="url(#steel)" stroke="#e5efec" stroke-width="2"/><path d="M167 108Q142 166 151 249q8 67 42 91h141q34-31 41-91 10-83-16-141z" fill="url(#steel)" stroke="#d7e2dd" stroke-width="3"/><ellipse cx="259" cy="111" rx="93" ry="20" fill="#17272c" stroke="#e7f0eb" stroke-width="6"/><ellipse cx="259" cy="113" rx="77" ry="13" fill="url(#food)"/><path d="M205 115q52-17 108 0" fill="none" stroke="#f0ffb1" stroke-width="2" opacity=".7" class="svg-ripple"/><path d="M229 111V218m0 0-37 21m37-21 38 21" stroke="#cddbd5" stroke-width="8" stroke-linecap="round"/><g fill="#d4f477"><circle cx="207" cy="160" r="4"/><circle cx="289" cy="179" r="5"/><circle cx="253" cy="206" r="3"/></g><ellipse cx="259" cy="229" rx="77" ry="35" fill="#86a955" opacity=".42" stroke="#d4f477" stroke-width="2"/><ellipse cx="259" cy="265" rx="79" ry="11" fill="none" stroke="#ff8c60" stroke-width="4"/><path d="M177 295q-16 43-4 53m172-53q16 43 4 53" fill="none" stroke="#829793" stroke-width="12" stroke-linecap="round"/><path d="M350 255h40v16h-40" fill="none" stroke="#dce7e2" stroke-width="9"/><circle cx="394" cy="263" r="17" fill="none" stroke="#d4f477" stroke-width="4"/><path d="M394 244v38" stroke="#ff8c60" stroke-width="5"/><rect x="207" y="147" width="104" height="27" rx="4" fill="#15272c" stroke="#d4f477"/><text x="259" y="165" text-anchor="middle" font-family="monospace" font-size="9" letter-spacing="2" fill="#d4f477">BATCH / 01</text></g></svg>`;holder.style.cssText='position:absolute;inset:38px 3% 38px;display:grid;place-items:center;z-index:3;pointer-events:none';holder.querySelector('svg').style.cssText='width:min(100%,475px);height:100%;filter:drop-shadow(0 20px 18px #0005)';canvas.after(holder)}
function bindGlobal(){window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';document.querySelector('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})});document.querySelector('#menu-toggle').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#global-search').onclick=()=>{document.querySelector('#search-dialog').showModal();document.querySelector('#search-input').focus()};document.querySelector('#search-input').oninput=e=>{const q=e.target.value.toLowerCase().trim(),hits=[...state.lots.filter(x=>`${x.id} ${x.name} ${x.supplier}`.toLowerCase().includes(q)).map(x=>({id:x.id,label:`${x.id} · ${x.name}`,type:'lot'})),...state.batches.filter(x=>`${x.id} ${x.product}`.toLowerCase().includes(q)).map(x=>({id:x.id,label:`${x.id} · ${x.product}`,type:'batch'})),...state.suppliers.filter(x=>x.name.toLowerCase().includes(q)).map(x=>({id:x.name,label:x.name,type:'supplier'}))].slice(0,8);document.querySelector('#search-results').innerHTML=q?hits.map(x=>`<button class="search-hit" data-search-hit="${esc(x.id)}" data-search-type="${x.type}">${esc(x.label)} <span>↗</span></button>`).join('')||'<p class="hint">No matching local records.</p>':''};document.querySelector('#search-results').onclick=e=>{const b=e.target.closest('[data-search-hit]');if(!b)return;document.querySelector('#search-dialog').close();if(b.dataset.searchType==='supplier')go('suppliers');else traceTo(b.dataset.searchHit)}}
function bindPage(){root.onclick=e=>{const goBtn=e.target.closest('[data-go]');if(goBtn){go(goBtn.dataset.go);return}const f=e.target.closest('[data-stock-filter]');if(f){stockFilter=f.dataset.stockFilter;render();return}const bf=e.target.closest('[data-batch-filter]');if(bf){batchFilter=bf.dataset.batchFilter;render();return}const tm=e.target.closest('[data-trace-mode]');if(tm){traceMode=tm.dataset.traceMode;render();return}const lot=e.target.closest('[data-lot-trace]');if(lot){traceTo(lot.dataset.lotTrace);return}const batch=e.target.closest('[data-batch-trace]');if(batch){traceTo(batch.dataset.batchTrace);return}const set=e.target.closest('[data-set-trace]');if(set){traceTo(set.dataset.setTrace);return}const release=e.target.closest('[data-release]');if(release){if(confirm(`Mark ${release.dataset.release} as released? Confirm your own checks before changing this demo status.`)){const b=state.batches.find(x=>x.id===release.dataset.release);b.status='Released';log('Batch state changed',`${b.id} manually marked Released`);save();render();toast('Demo status updated manually.')}return}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='trace-search'){traceQ=document.querySelector('#trace-input').value;render()}if(a.dataset.action==='mock-recall')mockRecall();if(a.dataset.action==='backup')exportBackup();if(a.dataset.action==='export-checks')exportChecks();if(a.dataset.action==='add-supplier')addSupplier();if(a.dataset.action==='reset-demo'){if(confirm('Replace the current local workspace with fictional starter records?')){state=structuredClone(starter);save();render();toast('Starter data restored.')}}if(a.dataset.action==='spin'){spinning=!spinning;a.innerText=spinning?'Ⅱ':'▶'}if(a.dataset.action==='reset-vessel'&&window.__batchlineReset){window.__batchlineReset();toast('Vessel view reset.')}return}};
root.oninput=e=>{if(e.target.id==='stock-search'){stockQ=e.target.value;const p=e.target.selectionStart;render();const x=document.querySelector('#stock-search');x.focus();x.setSelectionRange(p,p)}if(e.target.id==='batch-search'){batchQ=e.target.value;const p=e.target.selectionStart;render();const x=document.querySelector('#batch-search');x.focus();x.setSelectionRange(p,p)}};
root.onchange=e=>{if(e.target.matches('[name="lot"]')){const q=root.querySelector(`[data-use-qty="${CSS.escape(e.target.value)}"]`);q.disabled=!e.target.checked;if(e.target.checked)q.focus()}};
root.onsubmit=e=>{if(e.target.id==='dispatch-form'){e.preventDefault();addDispatch(e.target)}if(e.target.id==='lot-form'){e.preventDefault();addLot(e.target)}if(e.target.id==='batch-form'){e.preventDefault();addBatch(e.target)}if(e.target.id==='check-form'){e.preventDefault();const f=new FormData(e.target),c={id:`QC-${Date.now().toString().slice(-4)}`,type:f.get('type'),value:f.get('value'),time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),result:f.get('result'),batch:f.get('batch'),note:f.get('note')||'No note'};state.checks.unshift(c);if(c.result==='Fail / hold'&&c.batch){const b=state.batches.find(x=>x.id===c.batch);if(b)b.status='On hold'}log('Shift check recorded',`${c.type} · ${c.result}`);save();render();toast('Shift check saved locally.')}};

const importInput=document.querySelector('#restore-file');if(importInput)importInput.onchange=e=>{const f=e.target.files?.[0];if(f)restore(f)};
if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches){gsap.fromTo('.hero-copy > *',{opacity:0,y:14},{opacity:1,y:0,duration:.7,stagger:.08,ease:'power3.out',clearProps:'all'});gsap.fromTo('.stat',{opacity:0,y:8},{opacity:1,y:0,duration:.45,stagger:.08,delay:.22,ease:'power2.out',clearProps:'all'})}}
document.addEventListener('DOMContentLoaded',()=>{bindGlobal();render()});
})();
